export const API_TOKEN = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..XmKxpuI6ITrvsVyqvP3JnDD5-3HhyGkZwvs5A1OADew';

export const API_BASE_URL = 'https://app.healthcoversonline.com/api';

const getAuthHeaders = () => ({
  'Authorization': `Bearer ${API_TOKEN}`,
});

export const fetchApi = async (endpoint: string, params?: Record<string, any>) => {
  // Handle pagination parameters specifically for /gfe endpoint
  if (endpoint.startsWith('/gfe') && !endpoint.includes('?')) {
    const { pageNo = 1, pageSize = 10, ...otherParams } = params || {};
    const queryParams = new URLSearchParams({
      pageNo: pageNo.toString(),
      pageSize: pageSize.toString(),
      ...otherParams
    });
    endpoint = `${endpoint}?${queryParams.toString()}`;
  }

  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
    headers: getAuthHeaders(),
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => null);
    // Handle "no gfe found" as a valid state
    if (response.status === 404 || errorData?.message === 'no gfe found') {
      return { payload: [], pagination: { totalRecords: 0, totalPages: 0, pageNo: 1, pageSize: 10 } };
    }
    throw new Error(errorData?.message || `API request failed: ${response.statusText}`);
  }

  const data = await response.json();
  
  // Validate pagination response for /gfe endpoint
  if (endpoint.startsWith('/gfe') && params?.pageNo) {
    if (data.pagination?.pageNo !== params.pageNo) {
      throw new Error('Pagination mismatch: Received page number does not match requested page');
    }
  }

  return data;
};